import { MantineProvider } from "@mantine/core/lib/core/MantineProvider/MantineProvider";
import Home from "./pages/Home";

function App() {
  return (
    <MantineProvider
      theme={{
        colorScheme: "light",
        primaryColor: "blue",
      }}
    >
      <Home />
    </MantineProvider>
  )
}

export default App;
